package com.yourapp.sync

// The `uniffi.sync_core.*` package below is generated by:
//   cargo run --bin uniffi-bindgen generate --library <path-to-.so> \
//     --language kotlin --out-dir clients/android/generated
// plus the compiled .so bundled under app/src/main/jniLibs/<abi>/libsync_core.so
// (build per-ABI with `cargo ndk -t arm64-v8a -t x86_64 build --release`).
//
// Gradle deps this file assumes:
//   implementation "androidx.security:security-crypto:1.1.0"      // encryption key storage
//   implementation "androidx.work:work-runtime-ktx:2.9.0"          // background scheduling
import android.content.Context
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import androidx.work.*
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import uniffi.sync_core.EngineConfigFfi
import uniffi.sync_core.FieldValue
import uniffi.sync_core.LiveSyncListener
import uniffi.sync_core.SyncEngineHandle
import java.security.SecureRandom
import java.util.Base64
import java.util.concurrent.TimeUnit

/**
 * Thin, idiomatic Kotlin wrapper. All Rust core calls are blocking, so we
 * hop to Dispatchers.IO — this class is the only place Android-specific
 * concurrency handling lives; the sync logic itself is all in the core.
 */
class SyncEngine private constructor(private val handle: SyncEngineHandle) {

    companion object {
        private const val KEYSTORE_PREFS = "sync_engine_secure_prefs"
        private const val DB_KEY_PREF = "db_encryption_key"

        /**
         * Retrieves this device's local-DB encryption key from
         * EncryptedSharedPreferences (itself backed by the Android
         * Keystore), generating one on first run. The key never leaves the
         * device and is never sent to the server — losing it just means a
         * fresh local cache gets re-pulled from the server on next sync.
         */
        private fun getOrCreateEncryptionKey(context: Context): String {
            val masterKey = MasterKey.Builder(context)
                .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
                .build()
            val prefs = EncryptedSharedPreferences.create(
                context,
                KEYSTORE_PREFS,
                masterKey,
                EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM,
            )
            prefs.getString(DB_KEY_PREF, null)?.let { return it }

            val randomBytes = ByteArray(32)
            SecureRandom().nextBytes(randomBytes)
            val newKey = Base64.getEncoder().encodeToString(randomBytes)
            prefs.edit().putString(DB_KEY_PREF, newKey).apply()
            return newKey
        }

        fun create(
            context: Context,
            serverUrl: String,
            authToken: String,
            deviceId: String,
            userId: String,
        ): SyncEngine {
            val dbPath = context.getDatabasePath("sync.db").absolutePath
            val handle = SyncEngineHandle(
                EngineConfigFfi(
                    sqlitePath = dbPath,
                    dbEncryptionKey = getOrCreateEncryptionKey(context.applicationContext),
                    serverUrl = serverUrl,
                    authToken = authToken,
                    deviceId = deviceId,
                    userId = userId,
                )
            )
            return SyncEngine(handle)
        }
    }

    suspend fun upsert(table: String, rowId: String, fields: Map<String, Any?>, isInsert: Boolean) =
        withContext(Dispatchers.IO) {
            handle.applyLocalChange(
                table,
                rowId,
                if (isInsert) "insert" else "update",
                fields.mapValues { (_, v) -> toFieldValue(v) },
            )
        }

    suspend fun delete(table: String, rowId: String) = withContext(Dispatchers.IO) {
        handle.applyLocalChange(table, rowId, "delete", emptyMap())
    }

    /** Returns the merged row as a JSONObject, or null if absent/deleted. */
    suspend fun getRow(table: String, rowId: String): JSONObject? = withContext(Dispatchers.IO) {
        handle.getRowJson(table, rowId)?.let { JSONObject(it) }
    }

    /** Push local changes, pull remote changes. Call on app foreground,
     * network reconnect, a periodic WorkManager job, or after local writes. */
    suspend fun syncNow(): Pair<Int, Int> = withContext(Dispatchers.IO) {
        val result = handle.syncNow()
        result.pushed.toInt() to result.pulled.toInt()
    }

    /** Opens the near-real-time WebSocket connection. Call from onResume;
     * pair with stopLiveSync() in onPause — holding a socket open while
     * backgrounded doesn't work reliably (the OS suspends the process), so
     * background freshness comes from the WorkManager job below instead. */
    fun startLiveSync(onChanges: ((Int) -> Unit)? = null, onConnectionChange: ((Boolean) -> Unit)? = null) {
        handle.startLiveSync(object : LiveSyncListener {
            override fun onChangesApplied(count: UInt) { onChanges?.invoke(count.toInt()) }
            override fun onConnectionState(connected: Boolean) { onConnectionChange?.invoke(connected) }
        })
    }

    fun stopLiveSync() = handle.stopLiveSync()

    private fun toFieldValue(v: Any?): FieldValue = when (v) {
        null -> FieldValue.Null
        is String -> FieldValue.Text(v)
        is Boolean -> FieldValue.Bool(v)
        is Number -> FieldValue.Number(v.toDouble())
        else -> FieldValue.Text(v.toString())
    }
}

/**
 * Background sync via WorkManager — this is what makes offline devices
 * catch up even while the app isn't open, subject to Android's own Doze /
 * battery-optimization scheduling (WorkManager already handles backing off
 * appropriately under those constraints; we don't need to reinvent that).
 *
 * Register once, e.g. in Application.onCreate():
 *   BackgroundSync.schedule(applicationContext)
 */
class BackgroundSyncWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        return try {
            // Reconstruct engine params from wherever your app persists them
            // (e.g. its own EncryptedSharedPreferences entry for
            // serverUrl/authToken/deviceId/userId — the encryption key is
            // already recovered automatically inside SyncEngine.create()).
            val prefs = applicationContext.getSharedPreferences("sync_session", Context.MODE_PRIVATE)
            val serverUrl = prefs.getString("server_url", null) ?: return Result.success()
            val authToken = prefs.getString("auth_token", null) ?: return Result.success()
            val deviceId = prefs.getString("device_id", null) ?: return Result.success()
            val userId = prefs.getString("user_id", null) ?: return Result.success()

            val engine = SyncEngine.create(applicationContext, serverUrl, authToken, deviceId, userId)
            engine.syncNow()
            Result.success()
        } catch (e: Exception) {
            Result.retry() // WorkManager applies its own backoff policy (set below) between retries
        }
    }
}

object BackgroundSync {
    private const val WORK_NAME = "sync_engine_periodic"

    fun schedule(context: Context) {
        val constraints = Constraints.Builder()
            .setRequiredNetworkType(NetworkType.CONNECTED)
            .build()

        // 15 minutes is WorkManager's minimum periodic interval — it will
        // not run more often than that even if requested lower.
        val request = PeriodicWorkRequestBuilder<BackgroundSyncWorker>(15, TimeUnit.MINUTES)
            .setConstraints(constraints)
            .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, WorkRequest.MIN_BACKOFF_MILLIS, TimeUnit.MILLISECONDS)
            .build()

        WorkManager.getInstance(context).enqueueUniquePeriodicWork(
            WORK_NAME,
            ExistingPeriodicWorkPolicy.KEEP,
            request,
        )
    }

    fun cancel(context: Context) {
        WorkManager.getInstance(context).cancelUniqueWork(WORK_NAME)
    }
}

